<script lang="ts">
	import { preventDefault } from 'svelte/legacy';

	import { toast } from 'svelte-sonner';

	import { onMount, getContext } from 'svelte';

	import { getRAGConfig, updateRAGConfig } from '$lib/apis/retrieval';

	import { models } from '$lib/stores';

	import Switch from '$lib/components/common/Switch.svelte';
	import Selector from '$lib/components/common/Selector.svelte';
	import SensitiveInput from '$lib/components/common/SensitiveInput.svelte';
	import InfoCallout from '$lib/components/common/InfoCallout.svelte';
	import type { i18n as i18nType } from 'i18next';
	import type { Writable } from 'svelte/store';

	interface Props {
		onSave?: () => void;
	}

	let { onSave = () => {} }: Props = $props();

	const i18n: Writable<i18nType> = getContext<Writable<i18nType>>('i18n');

	// Vector DB
	let qdrantUrl = $state('');
	let qdrantApiKey = $state('');

	// Chunking
	let textSplitter = $state('');
	let chunkSize = $state(1000);
	let chunkOverlap = $state(100);

	// Cleansing
	let cleansingEnabled = $state(false);
	let cleansingModel = $state('');

	// Summary
	let summaryEnabled = $state(false);
	let summaryModel = $state('');

	// Embedding
	let embeddingModel = $state('');

	// Model items for searchable dropdowns (LLM models only, excludes embedding models)
	let modelItems = $derived($models.map((m) => ({ value: m.id, label: m.name })));

	const submitHandler = async () => {
		try {
			// Update RAG config (chunking + vector DB + embedding + cleansing + summary)
			await updateRAGConfig(localStorage.token, {
				chunk: {
					text_splitter: textSplitter,
					chunk_size: chunkSize,
					chunk_overlap: chunkOverlap
				},
				qdrant_url: qdrantUrl,
				qdrant_api_key: qdrantApiKey,
				embedding_model: embeddingModel,
				cleansing_enabled: cleansingEnabled,
				cleansing_model: cleansingModel,
				summary_enabled: summaryEnabled,
				summary_model: summaryModel
			});

			onSave?.();
		} catch (error) {
			toast.error(`${error}`);
		}
	};

	onMount(async () => {
		// Fetch RAG config
		try {
			const ragConfig = await getRAGConfig(localStorage.token);
			if (ragConfig) {
				textSplitter = ragConfig.chunk?.text_splitter ?? '';
				chunkSize = ragConfig.chunk?.chunk_size ?? 1000;
				chunkOverlap = ragConfig.chunk?.chunk_overlap ?? 100;

				qdrantUrl = ragConfig.qdrant_url ?? '';
				qdrantApiKey = ragConfig.qdrant_api_key ?? '';

				embeddingModel = ragConfig.embedding_model ?? '';

				cleansingEnabled = ragConfig.cleansing_enabled ?? false;
				cleansingModel = ragConfig.cleansing_model ?? '';

				summaryEnabled = ragConfig.summary_enabled ?? false;
				summaryModel = ragConfig.summary_model ?? '';
			}
		} catch (e) {
			console.warn('Failed to load RAG config:', e);
		}
	});
</script>

<form
	class="flex flex-col h-full justify-between space-y-3 text-sm"
	onsubmit={preventDefault(() => {
		submitHandler();
	})}
>
	<div class=" space-y-2.5 overflow-y-scroll scrollbar-hidden h-full pr-1.5">
		<div class="">
			<InfoCallout
				>{$i18n.t(
					'Configure retrieval settings such as the vector DB connection, chunking, embedding model, and reranking used to fetch relevant context.'
				)}</InfoCallout
			>
			<div class="mb-3">
				<div class=" mb-2.5 text-base font-medium">{$i18n.t('Vector DB')}</div>

				<hr class=" border-gray-100 dark:border-gray-850 my-2" />

				<div class=" mb-2.5 flex flex-col w-full">
					<div class=" mb-1 text-xs font-medium">{$i18n.t('Qdrant URL')}</div>
					<input
						class="flex-1 w-full rounded-lg text-sm dark:bg-gray-850 p-2 border-1 border-gray-300 dark:border-gray-700 focus:text-blue-600 focus:ring-0 focus:border-gray-400 dark:focus:border-gray-500"
						placeholder={$i18n.t('Enter Qdrant URL (e.g. http://localhost:6333)')}
						bind:value={qdrantUrl}
					/>
				</div>

				<div class=" mb-2.5 flex flex-col w-full">
					<div class=" mb-1 text-xs font-medium">
						{$i18n.t('Qdrant API Key')}
						<span class="text-xs text-gray-400 dark:text-gray-500">({$i18n.t('Optional')})</span>
					</div>
					<SensitiveInput
						placeholder={$i18n.t('Enter Qdrant API Key')}
						bind:value={qdrantApiKey}
						required={false}
					/>
				</div>
			</div>

			<div class="mb-3">
				<div class=" mb-2.5 text-base font-medium">{$i18n.t('Chunking')}</div>

				<hr class=" border-gray-100 dark:border-gray-850 my-2" />

				<div
					class="  mb-2.5 flex w-full justify-between pb-2 border-b-1 border-gray-100 dark:border-gray-700 border-dashed"
				>
					<div class=" self-center text-md font-medium">{$i18n.t('Text Splitter')}</div>
					<div class="flex items-center relative">
						<select
							class="dark:bg-gray-900 w-fit pr-8 rounded-sm px-2 text-xs bg-transparent outline-hidden text-right"
							bind:value={textSplitter}
						>
							<option value="">{$i18n.t('Default')} ({$i18n.t('Character')})</option>
							<option value="token">{$i18n.t('Token')} ({$i18n.t('Tiktoken')})</option>
						</select>
					</div>
				</div>

				<div
					class="  mb-2.5 flex w-full justify-between pb-2 border-b-1 border-gray-100 dark:border-gray-700 border-dashed"
				>
					<div class=" flex gap-1.5 w-full">
						<div class="  w-full justify-between">
							<div class="self-center text-xs font-medium min-w-fit mb-1">
								{$i18n.t('Chunk Size')}
							</div>
							<div class="self-center">
								<input
									class=" w-full rounded-lg py-1.5 px-4 text-sm bg-gray-50 dark:text-gray-300 dark:bg-gray-850 outline-hidden"
									type="number"
									placeholder={$i18n.t('Enter Chunk Size')}
									bind:value={chunkSize}
									autocomplete="off"
									min="0"
								/>
							</div>
						</div>

						<div class="w-full">
							<div class=" self-center text-md font-medium min-w-fit mb-1">
								{$i18n.t('Chunk Overlap')}
							</div>

							<div class="self-center">
								<input
									class="w-full rounded-lg py-1.5 px-4 text-sm bg-gray-50 dark:text-gray-300 dark:bg-gray-850 outline-hidden"
									type="number"
									placeholder={$i18n.t('Enter Chunk Overlap')}
									bind:value={chunkOverlap}
									autocomplete="off"
									min="0"
								/>
							</div>
						</div>
					</div>
				</div>
			</div>

			<div class="mb-3">
				<div class=" mb-2.5 text-base font-medium">{$i18n.t('Cleansing')}</div>

				<hr class=" border-gray-100 dark:border-gray-850 my-2" />

				<div
					class="  mb-2.5 flex w-full justify-between pb-2 border-b-1 border-gray-100 dark:border-gray-700 border-dashed"
				>
					<div class=" self-center text-md font-medium">{$i18n.t('Enable Cleansing')}</div>
					<div class="flex items-center relative">
						<Switch bind:state={cleansingEnabled} />
					</div>
				</div>

				{#if cleansingEnabled}
					<div class=" mb-2.5 flex flex-col w-full">
						<div class=" mb-1 text-xs font-medium">{$i18n.t('Cleansing Model')}</div>
						<div class="w-full">
							<Selector
								size="sm"
								bind:value={cleansingModel}
								placeholder={$i18n.t('Select a Cleansing Model')}
								searchPlaceholder={$i18n.t('Search a Cleansing Model')}
								items={modelItems}
							/>
						</div>
					</div>
				{/if}
			</div>

			<div class="mb-3">
				<div class=" mb-2.5 text-base font-medium">{$i18n.t('Summary')}</div>

				<hr class=" border-gray-100 dark:border-gray-850 my-2" />

				<div
					class="  mb-2.5 flex w-full justify-between pb-2 border-b-1 border-gray-100 dark:border-gray-700 border-dashed"
				>
					<div class=" self-center text-md font-medium">{$i18n.t('Enable Summary')}</div>
					<div class="flex items-center relative">
						<Switch bind:state={summaryEnabled} />
					</div>
				</div>

				{#if summaryEnabled}
					<div class=" mb-2.5 flex flex-col w-full">
						<div class=" mb-1 text-xs font-medium">{$i18n.t('Summary Model')}</div>
						<div class="w-full">
							<Selector
								size="sm"
								bind:value={summaryModel}
								placeholder={$i18n.t('Select a Summary Model')}
								searchPlaceholder={$i18n.t('Search a Summary Model')}
								items={modelItems}
							/>
						</div>
					</div>
				{/if}
			</div>

			<div class="mb-3">
				<div class=" mb-2.5 text-base font-medium">{$i18n.t('Embedding Model')}</div>

				<hr class=" border-gray-100 dark:border-gray-850 my-2" />

				<div class=" mb-2.5 flex flex-col w-full">
					<div class=" mb-1 text-xs font-medium">{$i18n.t('Embedding Model')}</div>
					<div class="w-full">
						<Selector
							size="sm"
							bind:value={embeddingModel}
							placeholder={$i18n.t('Select an Embedding Model')}
							searchPlaceholder={$i18n.t('Search an Embedding Model')}
							items={$models.map((m) => ({ value: m.id, label: m.name ?? m.id }))}
						/>
					</div>
					<div class="mt-1 mb-1 text-xs text-gray-400 dark:text-gray-500">
						{$i18n.t('When specified, a knowledge collection will be auto-created.')}
					</div>
				</div>
			</div>
		</div>
	</div>
	<div class="flex justify-end pt-3 text-sm font-medium">
		<button
			class="px-3.5 py-1.5 text-sm font-medium bg-black hover:bg-gray-900 text-white dark:bg-white dark:text-black dark:hover:bg-gray-100 transition rounded-full"
			type="submit"
		>
			{$i18n.t('Save')}
		</button>
	</div>
</form>
