<script lang="ts">
	import { get } from 'svelte/store';
	import { preventDefault } from 'svelte/legacy';

	import { getVersionUpdates, getWebhookUrl, updateWebhookUrl } from '$lib/apis';
	import {
		getAdminConfig,
		getLdapConfig,
		getLdapServer,
		updateAdminConfig,
		updateLdapConfig,
		updateLdapServer,
		uploadLogo,
		deleteLogo
	} from '$lib/apis/auths';
	import InfoCallout from '$lib/components/common/InfoCallout.svelte';
	import SensitiveInput from '$lib/components/common/SensitiveInput.svelte';
	import Switch from '$lib/components/common/Switch.svelte';
	import Tooltip from '$lib/components/common/Tooltip.svelte';
	import { WEBUI_BUILD_HASH, WEBUI_VERSION } from '$lib/constants';
	import { config, WEBUI_NAME } from '$lib/stores';
	import { compareVersion } from '$lib/utils';
	import { onMount, getContext } from 'svelte';
	import { toast } from 'svelte-sonner';
	import type { i18n as i18nType } from 'i18next';
	import type { Writable } from 'svelte/store';

	const i18n: Writable<i18nType> = getContext<Writable<i18nType>>('i18n');

	interface Props {
		saveHandler: () => void;
	}

	let { saveHandler }: Props = $props();

	let updateAvailable = null;
	let version = {
		current: '',
		latest: ''
	};

	let adminConfig = $state<Record<string, unknown> | null>(null);
	let webhookUrl = $state('');

	let logoInputElement: HTMLInputElement = $state();
	let logoPreviewUrl: string = $state('');

	// LDAP
	let ENABLE_LDAP = $state(false);
	let LDAP_SERVER = $state({
		label: '',
		host: '',
		port: '',
		attribute_for_mail: 'mail',
		attribute_for_username: 'uid',
		app_dn: '',
		app_dn_password: '',
		search_base: '',
		search_filters: '',
		use_tls: false,
		certificate_path: '',
		ciphers: ''
	});

	const checkForVersionUpdates = async () => {
		updateAvailable = null;
		version = await getVersionUpdates(localStorage.token).catch(() => {
			return {
				current: WEBUI_VERSION,
				latest: WEBUI_VERSION
			};
		});

		console.log(version);

		updateAvailable = compareVersion(version.latest, version.current);
		console.log(updateAvailable);
	};

	const updateLdapServerHandler = async () => {
		if (!ENABLE_LDAP) return;
		const res = await updateLdapServer(localStorage.token, LDAP_SERVER).catch((error) => {
			toast.error(`${error}`);
			return null;
		});
		if (res) {
			toast.success($i18n.t('LDAP server updated'));
		}
	};

	const updateHandler = async () => {
		webhookUrl = await updateWebhookUrl(localStorage.token, webhookUrl);
		const res = await updateAdminConfig(localStorage.token, adminConfig);
		await updateLdapServerHandler();

		if (res) {
			if (adminConfig.name) {
				WEBUI_NAME.set(adminConfig.name);
			}
			saveHandler();
		} else {
			toast.error($i18n.t('Failed to update settings'));
		}
	};

	const uploadLogoHandler = async () => {
		const logoInputFile = logoInputElement.files[0];
		if (!logoInputFile) return;

		const res = await uploadLogo(localStorage.token, logoInputFile).catch((error) => {
			toast.error(`${error}`);
			return null;
		});

		if (res) {
			adminConfig.logo_url = res.logo_url;
			logoPreviewUrl = res.logo_url;
			config.set({ ...get(config), logo_url: `${res.logo_url}?t=${Date.now()}` });
			toast.success($i18n.t('Logo updated successfully'));
		}
	};

	const deleteLogoHandler = async () => {
		const res = await deleteLogo(localStorage.token).catch((error) => {
			toast.error(`${error}`);
			return null;
		});

		if (res) {
			adminConfig.logo_url = '';
			logoPreviewUrl = '';
			config.set({ ...get(config), logo_url: '' });
			toast.success($i18n.t('Logo removed'));
		}
	};

	onMount(async () => {
		checkForVersionUpdates();

		await Promise.all([
			(async () => {
				adminConfig = await getAdminConfig(localStorage.token);
				logoPreviewUrl = adminConfig?.logo_url || '';
			})(),

			(async () => {
				webhookUrl = await getWebhookUrl(localStorage.token);
			})(),
			(async () => {
				LDAP_SERVER = await getLdapServer(localStorage.token);
			})()
		]);

		const ldapConfig = await getLdapConfig(localStorage.token);
		ENABLE_LDAP = ldapConfig.ENABLE_LDAP;
	});
</script>

