<script lang="ts">
	import { preventDefault } from 'svelte/legacy';
	import { onMount, getContext } from 'svelte';
	import { toast } from 'svelte-sonner';

	import {
		getAuditConfig,
		updateAuditConfig,
		purgeAuditLogs
	} from '$lib/apis/audit';
	import type { AuditConfig } from '$lib/apis/audit';

	import InfoCallout from '$lib/components/common/InfoCallout.svelte';

	import type { Writable } from 'svelte/store';
	import type { i18n as i18nType } from 'i18next';

	const i18n = getContext<Writable<i18nType>>('i18n');

	interface Props {
		saveHandler: () => void;
	}

	let { saveHandler }: Props = $props();

	let config: AuditConfig | null = $state(null);
	let loading = $state(true);
	let showPurgeConfirm = $state(false);
	let purgeResult = $state<{ deleted: number } | null>(null);
	let purgeLoading = $state(false);

	const submitHandler = async () => {
		if (!config) return;
		const res = await updateAuditConfig(localStorage.token, config);
		if (res) {
			saveHandler();
		}
	};

	const confirmPurge = async () => {
		if (!config) return;
		purgeLoading = true;
		try {
			const res = await purgeAuditLogs(localStorage.token, config.audit_retention_days);
			purgeResult = res;
			toast.success($i18n.t('Deleted {{count}} log entries', { count: res.deleted }));
		} catch {
			toast.error($i18n.t('Failed to purge logs'));
		}
		purgeLoading = false;
		showPurgeConfirm = false;
	};

	const cancelPurge = () => {
		showPurgeConfirm = false;
	};

	onMount(async () => {
		const res = await getAuditConfig(localStorage.token);
		if (res) {
			config = res;
		}
		loading = false;
	});
</script>

{#if !loading && config}
	<form
		class="flex flex-col h-full justify-between space-y-3 text-sm"
		onsubmit={preventDefault(submitHandler)}
	>
		<div class="space-y-3 overflow-y-scroll scrollbar-hidden h-full">
			<InfoCallout
				>{$i18n.t(
					'Configure audit logging level, retention policy, and data capture settings. Changes are applied system-wide.'
				)}</InfoCallout
			>
			<div class="flex flex-col gap-3">
					<div
					class="rounded-lg border p-3 {config.audit_log_level === 'NONE'
						? 'border-red-500/50 bg-red-50 dark:border-red-500/30 dark:bg-red-950/20'
						: 'border-green-500/50 bg-green-50 dark:border-green-500/30 dark:bg-green-950/20'}"
				>
					<div class="flex w-full justify-between items-center">
						<div class="flex items-center gap-2">
							<span
								class="inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium {config.audit_log_level ===
								'NONE'
									? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
									: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'}"
							>
								{config.audit_log_level === 'NONE'
									? $i18n.t('Disabled')
									: $i18n.t('Active')}
							</span>
							{#if config.audit_log_level !== 'NONE'}
								<span class="text-xs text-gray-500 dark:text-gray-400">
									{config.audit_log_level}
								</span>
							{:else}
								<span class="text-xs text-gray-500 dark:text-gray-400">
									{$i18n.t('Audit logging is disabled')}
								</span>
							{/if}
						</div>
						<a
							href="/admin/audit"
							class="text-xs text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
						>
							{$i18n.t('View audit logs')}
						</a>
					</div>
				</div>

				<hr class="border-gray-100 dark:border-gray-850" />

				<div>
					<div class="py-0.5 flex w-full justify-between">
						<div>
							<div class="font-medium">{$i18n.t('Audit Logging Level')}</div>
							<div class="text-xs text-gray-500 dark:text-gray-400">
								{$i18n.t(
									'Controls what information is captured in audit logs. Changes take effect immediately.'
								)}
							</div>
						</div>
					</div>
					<div class="mt-2">
						<select
							class="dark:bg-gray-900 w-full cursor-pointer rounded-lg px-3 py-2 text-sm bg-transparent outline-hidden border border-gray-200 dark:border-gray-700"
							bind:value={config.audit_log_level}
						>
							<option value="NONE">{$i18n.t('NONE')}: {$i18n.t('Disabled - No audit logging')}</option>
							<option value="METADATA"
								>{$i18n.t('METADATA')}: {$i18n.t(
									'Metadata - Log HTTP method, path, status, user, IP'
								)}</option
							>
							<option value="REQUEST"
								>{$i18n.t('REQUEST')}: {$i18n.t('Request - Metadata + request body capture')}</option
							>
							<option value="REQUEST_RESPONSE"
								>{$i18n.t('REQUEST_RESPONSE')}: {$i18n.t(
									'Full - Request + response body capture (highest detail)'
								)}</option
							>
						</select>
					</div>
				</div>

				<hr class="border-gray-100 dark:border-gray-850" />

				<div>
					<div class="py-0.5 flex w-full justify-between">
						<div>
							<div class="font-medium">{$i18n.t('Log Retention (days)')}</div>
							<div class="text-xs text-gray-500 dark:text-gray-400">
								{$i18n.t(
									'Automatically delete audit logs older than this many days. Set to 0 for unlimited retention.'
								)}
							</div>
						</div>
						<input
							type="number"
							min="0"
							step="1"
							class="w-24 rounded-lg py-1 px-2 text-sm bg-transparent outline-hidden border border-gray-200 dark:border-gray-700 text-right"
							bind:value={config.audit_retention_days}
						/>
					</div>
					{#if config.audit_retention_days === 0}
						<div
							class="mt-2 rounded px-2 py-1 text-xs font-medium bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-300"
						>
							{$i18n.t('Unlimited retention may consume significant disk space over time')}
						</div>
					{/if}
				</div>

				<hr class="border-gray-100 dark:border-gray-850" />

				<div>
					<div class="py-0.5 flex w-full justify-between">
						<div>
							<div class="font-medium">{$i18n.t('Max Body Capture Size (bytes)')}</div>
							<div class="text-xs text-gray-500 dark:text-gray-400">
								{$i18n.t(
									'Maximum size of request/response body to capture per log entry'
								)}
							</div>
						</div>
						<div class="flex items-center gap-2">
							{#if config.max_body_log_size > 0}
								<span class="text-xs text-gray-400">
									{Math.round((config.max_body_log_size / 1024) * 10) / 10} KB
								</span>
							{/if}
							<input
								type="number"
								min="0"
								step="256"
								class="w-24 rounded-lg py-1 px-2 text-sm bg-transparent outline-hidden border border-gray-200 dark:border-gray-700 text-right"
								bind:value={config.max_body_log_size}
							/>
						</div>
					</div>
				</div>

				<hr class="border-gray-100 dark:border-gray-850" />

				<div>
					<div class="font-medium mb-1">{$i18n.t('Excluded API Paths')}</div>
					<div class="text-xs text-gray-500 dark:text-gray-400 mb-2">
						{$i18n.t(
							'Comma-separated list of API path prefixes to exclude from audit logging'
						)}
					</div>
					<textarea
						class="w-full rounded-lg py-2 px-3 text-sm bg-transparent outline-hidden border border-gray-200 dark:border-gray-700 resize-y min-h-[60px]"
						placeholder="chats, chat, folders"
						bind:value={config.audit_excluded_paths}
						rows="3"
					></textarea>
				</div>

				<hr class="border-gray-100 dark:border-gray-850" />

				<div>
					<div class="font-medium mb-1">{$i18n.t('Log File Rotation Size')}</div>
					<div class="text-xs text-gray-500 dark:text-gray-400 mb-2">
						{$i18n.t(
							'Size threshold for audit log file rotation (e.g., 10MB, 50MB)'
						)}
					</div>
					<input
						type="text"
						class="w-full rounded-lg py-2 px-3 text-sm bg-transparent outline-hidden border border-gray-200 dark:border-gray-700"
						placeholder="10 MB"
						bind:value={config.audit_log_file_rotation_size}
					/>
				</div>

				<hr class="border-gray-100 dark:border-gray-850" />

				<div>
					<div class="font-medium mb-1">{$i18n.t('Purge Expired Logs')}</div>
					<div class="text-xs text-gray-500 dark:text-gray-400 mb-2">
						{$i18n.t(
							'Manually trigger deletion of logs older than the configured retention period'
						)}
					</div>
					<div class="flex items-center gap-3">
						<button
							type="button"
							class="px-3.5 py-1.5 text-sm font-medium rounded-lg border border-red-300 dark:border-red-700 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/30 transition"
							onclick={() => {
								showPurgeConfirm = true;
							}}
						>
							{$i18n.t('Purge Now')}
						</button>
						{#if purgeResult}
							<span class="text-xs text-gray-500 dark:text-gray-400">
								{$i18n.t('Deleted {{count}} log entries', { count: purgeResult.deleted })}
							</span>
						{/if}
					</div>
				</div>
			</div>
		</div>

		<div class="flex justify-end pt-3 text-sm font-medium">
			<button
				class="px-3.5 py-1.5 text-sm font-medium bg-black hover:bg-gray-900 text-white dark:bg-white dark:text-black dark:hover:bg-gray-100 transition rounded-full"
				type="submit"
			>
				{$i18n.t('Save')}
			</button>
		</div>
	</form>

	{#if showPurgeConfirm}
		<div
			class="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
		>
			<div
				class="bg-white dark:bg-gray-800 rounded-xl shadow-2xl p-5 max-w-md w-full mx-4 border border-red-500/30"
			>
				<div class="flex items-center gap-3 mb-3">
					<h3 class="text-lg font-semibold text-red-600 dark:text-red-400">
						{$i18n.t('Confirm Purge')}
					</h3>
				</div>
				<p class="text-sm text-gray-600 dark:text-gray-300 mb-1">
					{$i18n.t(
						'Are you sure you want to purge audit logs older than {{days}} days?',
						{ days: config?.audit_retention_days ?? 90 }
					)}
				</p>
				<p class="text-sm font-medium text-red-600 dark:text-red-400 mb-5">
					{$i18n.t('This action cannot be undone.')}
				</p>
				<div class="flex justify-end gap-2">
					<button
						class="px-4 py-2 text-sm font-medium rounded-lg border border-gray-300 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700 transition"
						onclick={cancelPurge}
					>
						{$i18n.t('Cancel')}
					</button>
					<button
						class="px-4 py-2 text-sm font-medium rounded-lg bg-red-600 hover:bg-red-700 text-white transition"
						onclick={confirmPurge}
						disabled={purgeLoading}
					>
						{purgeLoading ? $i18n.t('Purging...') : $i18n.t('Purge')}
					</button>
				</div>
			</div>
		</div>
	{/if}
{/if}
