									<div class="font-medium">{$i18n.t('Webhook Notification')}</div>
									<div class="text-xs text-gray-500 dark:text-gray-400">
										{$i18n.t('Send webhook when a new handoff request is created')}
									</div>
								</div>
								<Switch bind:state={handoffConfig.webhook_enabled} />
							</div>
							{#if handoffConfig.webhook_enabled}
								<div class="pt-1">
									<div class="text-xs font-medium mb-1">{$i18n.t('Webhook URL')}</div>
									<input
										type="text"
										class="w-full rounded-lg py-2 px-3 text-sm bg-transparent outline-hidden border border-gray-200 dark:border-gray-700"
										placeholder="https://hooks.example.com/handoff"
										bind:value={handoffConfig.webhook_url}
									/>
								</div>
							{/if}
						</div>

						<div class="py-2 px-3 rounded-lg bg-gray-50 dark:bg-gray-850">
							<div class="flex items-center justify-between">
								<div>
									<div class="font-medium">{$i18n.t('WebSocket Notification')}</div>
									<div class="text-xs text-gray-500 dark:text-gray-400">
										{$i18n.t('Automatically sends real-time notifications via WebSocket')}
									</div>
								</div>
								<span class="text-xs text-gray-400">{$i18n.t('Always on')}</span>
							</div>
						</div>

						<div class="flex justify-end">
							<button
								class="px-3.5 py-1.5 text-sm font-medium bg-black hover:bg-gray-900 text-white dark:bg-white dark:text-black dark:hover:bg-gray-100 transition rounded-full"
								onclick={submitHandoffHandler}
							>
								{$i18n.t('Save')}
							</button>
						</div>
					{/if}
				</div>
			</div>
		</div>
	{/if}
{/if}
